{
  "name": "Grove 16×2 RGB背光字符液晶屏",
  "name_en": "Grove 16x2 RGB Backlight Character LCD",
  "manufacturer": "Seeed Studio",
  "description": "这是一款 Grove 接口的 I2C 16×2 字符液晶显示模块，带 RGB 或单色背光，可用于在实验系统中显示传感器读数、设备状态、菜单和提示信息。",
  "description_en": "This is a Grove I2C 16x2 character LCD module with RGB or monochrome backlight, used in laboratory setups to display sensor readings, device status, menus, and user prompts.",
  "actions": [
    {
      "action_name": "auto-clearDisplay",
      "description": "清空液晶屏显示内容。",
      "description_en": "Clear the LCD display contents."
    },
    {
      "action_name": "auto-display_backlight_color",
      "description": "按给定的 RGB 颜色值设置背光颜色。",
      "description_en": "Set the backlight color using the provided RGB values."
    },
    {
      "action_name": "auto-lcd_backlight",
      "description": "打开或关闭液晶屏背光。",
      "description_en": "Turn the LCD backlight on or off."
    },
    {
      "action_name": "auto-lcd_byte",
      "description": "向液晶屏发送一个字节，作为命令或显示数据。",
      "description_en": "Send one byte to the LCD as either a command or display data."
    },
    {
      "action_name": "auto-lcd_init",
      "description": "初始化液晶屏以开始显示。",
      "description_en": "Initialize the LCD for operation."
    },
    {
      "action_name": "auto-lcd_string_write",
      "description": "将字符串写入指定显示行。",
      "description_en": "Write a string to a specified display line."
    },
    {
      "action_name": "auto-lcd_toggle_enable",
      "description": "切换液晶屏的使能信号。",
      "description_en": "Toggle the LCD enable signal."
    },
    {
      "action_name": "auto-lcd_write_lines",
      "description": "将提供的多行文本写入液晶屏显示。",
      "description_en": "Write the provided multiple text lines to the LCD display."
    },
    {
      "action_name": "auto-setCursor",
      "description": "设置光标所在的行列位置。",
      "description_en": "Set the cursor position by row and column."
    },
    {
      "action_name": "auto-setRGB",
      "description": "设置背光的红、绿、蓝亮度值。",
      "description_en": "Set the red, green, and blue backlight levels."
    },
    {
      "action_name": "auto-setText",
      "description": "设置液晶屏显示文本。",
      "description_en": "Set the text shown on the LCD."
    },
    {
      "action_name": "auto-writeCommand",
      "description": "向液晶控制器发送底层命令。",
      "description_en": "Send a low-level command to the LCD controller."
    },
    {
      "action_name": "auto-writeData",
      "description": "向液晶控制器发送底层显示数据。",
      "description_en": "Send low-level display data to the LCD controller."
    }
  ],
  "tag_hints": [
    "character LCD",
    "RGB backlight",
    "Grove module",
    "I2C display",
    "16x2 LCD",
    "status display",
    "instrument readout"
  ]
}

